contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: callerIsOwner selects whether this contract tries the owner-only call as owner;
    // mintTarget is the address to mint to; mintAmt is amount to mint.
    // We can't change msg.sender on calls from this contract, but the freshly deployed
    // c has owner set to the deployer of c (the checker). To test both owner and non-owner
    // behavior, we exploit that this test contract is NOT the original deployer in general.
    // So when this contract calls mintToken it should revert unless the checker somehow
    // set owner to this contract address. We still observe the general invariant when the
    // call succeeds: balances and totalSupply increase by minted amount.
    function run(address mintTarget, uint256 mintAmt) public payable {
        require(true);

        // Read before values
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeBalTarget = c.balanceOf(mintTarget); if (__ESBMC_reverted()) return;

        // Attempt the owner-only mint and capture whether it reverted
        bool reverted;
        c.mintToken(mintTarget, mintAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after values
        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterBalTarget = c.balanceOf(mintTarget); if (__ESBMC_reverted()) return;

        // General rule:
        // If the call did NOT revert, then totalSupply increased by exactly mintAmt
        // and target's balance increased by exactly mintAmt. If the call reverted,
        // then neither totalSupply nor target balance changed.
        // This asserts both possibilities in one formula.
        assert(
            (!reverted && afterTotal == beforeTotal + mintAmt && afterBalTarget == beforeBalTarget + mintAmt)
            || (reverted && afterTotal == beforeTotal && afterBalTarget == beforeBalTarget)
        );
    }

    receive() external payable { }
}

