// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address mintTarget, uint256 mintAmt) internal {
        vm.assume(true);
        uint256 beforeTotal;
        try c.totalSupply() returns (uint256 __r) { beforeTotal = __r; } catch { return; }
        uint256 beforeBalTarget;
        try c.balanceOf(mintTarget) returns (uint256 __r) { beforeBalTarget = __r; } catch { return; }
        bool reverted;
        try c.mintToken(mintTarget, mintAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotal;
        try c.totalSupply() returns (uint256 __r) { afterTotal = __r; } catch { return; }
        uint256 afterBalTarget;
        try c.balanceOf(mintTarget) returns (uint256 __r) { afterBalTarget = __r; } catch { return; }
        assertTrue((!reverted && afterTotal == beforeTotal + mintAmt && afterBalTarget == beforeBalTarget + mintAmt)
            || (reverted && afterTotal == beforeTotal && afterBalTarget == beforeBalTarget));
    }

    function testFuzz_run(address mintTarget, uint256 mintAmt) public {
        vm.assume(mintTarget.code.length == 0 && uint160(mintTarget) > 0xffff && mintTarget != address(this) && mintTarget != address(c) && mintTarget != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && mintTarget != 0x000000000000000000636F6e736F6c652e6c6f67 && mintTarget != 0x4e59b44847b379578588920cA78FbF26c0B4956C && mintTarget != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(mintTarget, mintAmt);
    }

    receive() external payable { }
}
